/** warehouse.damage.reported: A damaged unit is found at pick or pack */
export interface WarehouseDamageReportedEvent {
  fulfillmentId: string;
  orderId: string;
  stockItemId: string;
  quantity: number;
  discrepancyId: string;
}

export const WarehouseDamageReportedEvent: z.ZodType<WarehouseDamageReportedEvent> = z.object({
  fulfillmentId: z.uuid(),
  orderId: z.uuid(),
  stockItemId: z.uuid(),
  quantity: z.number().int(),
  discrepancyId: z.uuid(),
});

/** warehouse.package.packed: A package is packed with its label */
export interface WarehousePackagePackedEvent {
  packageId: string;
  fulfillmentId: string;
  orderId: string;
  sellerGroupId: string;
  items: PackageItem[];
  carrier: string;
  service: string;
  trackingNumber: string;
  weight: Weight;
  dimensions?: Dimensions | null;
}

export const WarehousePackagePackedEvent: z.ZodType<WarehousePackagePackedEvent> = z.object({
  packageId: z.uuid(),
  fulfillmentId: z.uuid(),
  orderId: z.uuid(),
  sellerGroupId: z.uuid(),
  get items() {
    return z.array(PackageItem);
  },
  carrier: z.string(),
  service: z.string(),
  trackingNumber: z.string(),
  get weight() {
    return Weight;
  },
  get dimensions() {
    return Dimensions.nullish();
  },
});

/** warehouse.bin.assigned: A stock item's bins change or put-away completes */
export interface WarehouseBinAssignedEvent {
  stockItemId: string;
  binId: string;
  binCode: string;
  primary: boolean;
}

export const WarehouseBinAssignedEvent: z.ZodType<WarehouseBinAssignedEvent> = z.object({
  stockItemId: z.uuid(),
  binId: z.uuid(),
  binCode: z.string(),
  primary: z.boolean(),
});

/** warehouse.return_parcel.received: A return parcel is scanned in at the warehouse */
export interface WarehouseReturnParcelReceivedEvent {
  parcelId: string;
  returnId?: string | null;
  unexpected: boolean;
  parcelCondition: string;
  receivedAt: string;
}

export const WarehouseReturnParcelReceivedEvent: z.ZodType<WarehouseReturnParcelReceivedEvent> = z.object({
  parcelId: z.uuid(),
  returnId: z.uuid().nullish(),
  unexpected: z.boolean(),
  parcelCondition: z.string(),
  receivedAt: z.iso.datetime({ offset: true }),
});

/** warehouse.return_parcel.handed_over: A parcel is handed to returns inspection */
export interface WarehouseReturnParcelHandedOverEvent {
  parcelId: string;
  returnId?: string | null;
  inspectorId?: string | null;
}

export const WarehouseReturnParcelHandedOverEvent: z.ZodType<WarehouseReturnParcelHandedOverEvent> = z.object({
  parcelId: z.uuid(),
  returnId: z.uuid().nullish(),
  inspectorId: z.uuid().nullish(),
});

/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('warehouse')` (or `ctx.tryUse` for an optional dependency). */
export interface WarehousePublicApi {
  /** Serial numbers recorded at packing per order item, for the return inspection checklist ('Serial number matches order') Used by: returns. */
  getShippedSerials(orderItemIds: string[]): Promise<Record<string, string[]>>;
  /** Warehouse progress for an order's Official Store group (picking, packed, on hold) Used by: orders, support. */
  getFulfillmentForOrder(orderId: string): Promise<Fulfillment | null>;
  /** Primary bin, or a free bin in the item's zone, for put-away suggestions on receipts Used by: purchasing. */
  suggestBin(stockItemId: string, locationId: string): Promise<Bin | null>;
  /** Warehouse task per order seller group (null for groups outside sellers ship), batched for the admin order view Used by: graphql. */
  getTasksForOrderGroups(sellerGroupIds: string[]): Promise<Record<string, Fulfillment | null>>;
  /** Today's Official Store warehouse work (OpsQueues): to pick, to pack, packed waiting for pickup, dispatched today, on hold, at risk and late (ship-by passed, not dispatched), the next carrier pickup as the ship-by cutoff, and the most urgent tasks. Same counts as GET /summary. Used by: graphql. */
  getTodaySummary(locationId?: string): Promise<WarehouseSummary & { date: string, toShip: number, shipToday: number, dispatchedToday: number, late: number, shipByCutoff: string | null, pickupsToday: string[], urgent: Fulfillment[] }>;
}

/* ------------------------------------------------------------------ tables (Kysely row types) */

/** Tables in the `warehouse` schema. Use with `ctx.db` (already scoped to the schema). */
export interface WarehouseDb {
  bins: {
    id: string;
    location_id: string;
    code: string;
    zone: string;
    kind: string;
    barcode: string;
    active: boolean;
  };
  /** Which stock items are stored in which bins */
  bin_assignments: {
    stock_item_id: string;
    bin_id: string;
    primary_bin: boolean;
    assigned_at: Date;
  };
  /** One per Official Store seller group of an accepted order */
  fulfillments: {
    id: string;
    order_id: string;
    order_ref: string;
    seller_group_id: string;
    location_id: string;
    status: string;
    ship_by: Date;
    delivery_choice: string;
    ship_to: Json;
    wave_id: string | null;
    hold_reason: string | null;
    discrepancy_ids: Json;
    total_packages_in_order: number;
    created_at: Date;
    updated_at: Date;
  };
  fulfillment_lines: {
    id: string;
    fulfillment_id: string;
    order_item_id: string;
    stock_item_id: string;
    sku: string;
    label: string;
    quantity: number;
    bin_code: string | null;
    picked: number;
    short: number;
    state: string;
    picked_by: string | null;
    picked_at: Date | null;
  };
  waves: {
    id: string;
    ref: string;
    location_id: string;
    status: string;
    carrier_pickup_at: Date | null;
    created_by: string;
    created_at: Date;
    completed_at: Date | null;
  };
  /** Every scan at pick, pack, put-away and returns (troubleshooting and productivity) */
  scan_log: {
    id: string;
    context: string;
    context_id: string | null;
    code: string;
    result: string;
    actor_id: string;
    station: string | null;
    at: Date;
  };
  box_types: {
    id: string;
    name: string;
    kind: string;
    dimensions: Json;
    max_weight: Json | null;
    active: boolean;
  };
  packages: {
    id: string;
    fulfillment_id: string;
    index_in_order: number;
    of_in_order: number;
    status: string;
    box_type_id: string | null;
    dimensions: Json | null;
    weight: Json | null;
    fragile: boolean;
    handling_note: string | null;
    carrier: string | null;
    service: string | null;
    tracking_number: string | null;
    label_media_id: string | null;
    label_idempotency_key: string | null;
    shipment_id: string | null;
    packed_by: string | null;
    packed_at: Date | null;
    station: string | null;
  };
  package_items: {
    package_id: string;
    order_item_id: string;
    stock_item_id: string;
    quantity: number;
    scanned: number;
    serial_numbers: string[];
  };
  putaway_tasks: {
    id: string;
    receipt_id: string;
    receipt_ref: string;
    location_id: string;
    stock_item_id: string;
    quantity: number;
    suggested_bin_code: string | null;
    bin_code: string | null;
    status: string;
    done_by: string | null;
    done_at: Date | null;
  };
  return_parcels: {
    id: string;
    location_id: string;
    return_id: string | null;
    return_ref: string | null;
    order_ref: string | null;
    tracking_number: string | null;
    status: string;
    expected_by: string | null;
    expected_items: Json;
    unexpected: boolean;
    parcel_condition: string | null;
    photo_media_ids: Json;
    note: string | null;
    received_by: string | null;
    received_at: Date | null;
    handed_over_to: string | null;
    handed_over_at: Date | null;
  };
}

